#!/usr/bin/env node
/**
 * Validates commit titles, PR titles, and branch names against the repo's
 * conventions (see .claude/skills/commit-conventions/SKILL.md).
 *
 * Usage:
 *   node check-git-conventions.mjs title "feat(web): add thing"
 *   node check-git-conventions.mjs branch "feat/api-users-crud"
 *   node check-git-conventions.mjs commits <base-sha> <head-sha>
 */
import { execFileSync } from 'node:child_process';

const TYPES = [
  'feat', 'fix', 'refactor', 'perf', 'docs', 'test', 'chore',
  'ci', 'build', 'style', 'revert',
];

const SCOPES = [
  'web', 'backend', 'ui', 'types', 'config', 'auth', 'db', 'cache',
  'queue', 'docker', 'installer', 'ci', 'deps', 'repo', 'skills', 'infra',
];

const TITLE_RE = new RegExp(
  `^(${TYPES.join('|')})(\\(([a-z0-9-]+)\\))?(!)?: (.+)$`,
);

function checkTitle(title, label) {
  const errors = [];

  // Revert commits generated by git/GitHub are allowed as-is.
  if (/^Revert ".*"$/.test(title)) return errors;

  const m = title.match(TITLE_RE);
  if (!m) {
    errors.push(
      `${label}: "${title}" does not match "type(scope): summary". ` +
      `Types: ${TYPES.join(', ')}.`,
    );
    return errors;
  }

  const scope = m[3];
  const summary = m[5];

  if (scope && !SCOPES.includes(scope)) {
    errors.push(
      `${label}: unknown scope "${scope}". Allowed: ${SCOPES.join(', ')}.`,
    );
  }
  if (scope && scope.includes(',')) {
    errors.push(`${label}: one scope only — split the change instead.`);
  }
  if (title.length > 70) {
    errors.push(`${label}: title is ${title.length} chars (max 70).`);
  }
  if (/[.]$/.test(summary)) {
    errors.push(`${label}: no trailing period in the summary.`);
  }
  if (/^[A-Z]/.test(summary)) {
    errors.push(
      `${label}: summary must start lowercase (proper nouns later in the ` +
      `summary keep their case).`,
    );
  }
  if (/#\d+/.test(title)) {
    errors.push(`${label}: no issue numbers in titles — use a Refs/Closes footer.`);
  }
  if (/^(added|adds|adding|fixed|fixes|fixing|updated|updates|updating|changed|changes)\b/.test(summary)) {
    errors.push(`${label}: use imperative mood ("add", not "added"/"adds").`);
  }
  if (/^(misc|update|cleanup|wip)\b/i.test(summary)) {
    errors.push(`${label}: vague summary ("${summary.split(' ')[0]}") — say what changed.`);
  }
  return errors;
}

function checkBranch(name) {
  if (['main'].includes(name) || name.startsWith('dependabot/') || name.startsWith('renovate/')) {
    return [];
  }
  const re = new RegExp(`^(${TYPES.join('|')})/[a-z0-9][a-z0-9-]*$`);
  if (!re.test(name)) {
    return [
      `branch: "${name}" does not match "type/short-kebab-summary" ` +
      `(e.g. feat/api-users-crud). Types: ${TYPES.join(', ')}.`,
    ];
  }
  if (name.length > 60) {
    return [`branch: "${name}" is ${name.length} chars — keep it ~50.`];
  }
  return [];
}

function checkCommits(base, head) {
  const out = execFileSync(
    'git',
    ['log', '--no-merges', '--format=%H%x00%s', `${base}..${head}`],
    { encoding: 'utf8' },
  ).trim();
  if (!out) return [];
  return out.split('\n').flatMap((line) => {
    const [sha, subject] = line.split('\0');
    return checkTitle(subject, `commit ${sha.slice(0, 7)}`);
  });
}

const [mode, ...rest] = process.argv.slice(2);
let errors;
switch (mode) {
  case 'title':
    errors = checkTitle(rest.join(' '), 'PR title');
    break;
  case 'branch':
    errors = checkBranch(rest[0] ?? '');
    break;
  case 'commits':
    errors = checkCommits(rest[0], rest[1]);
    break;
  default:
    console.error('usage: check-git-conventions.mjs <title|branch|commits> ...');
    process.exit(2);
}

if (errors.length) {
  for (const e of errors) console.error(`✖ ${e}`);
  process.exit(1);
}
console.log(`✔ ${mode} check passed`);
